INSERT INTO comments (page, name, body, created_at, date_precision, status, source, flag_reason)
  VALUES ('blog/wenn-tonbänder-im-backofen-schmoren', 'Scott S. Walker', 'Der Artikel zeigt auf unterhaltsame Weise, wie wichtig die professionelle Restaurierung und Digitalisierung alter Tonbänder sein kann. Besonders spannend finde ich, dass die scheinbar ungewöhnliche Methode des vorsichtigen Erwärmens tatsächlich Teil eines professionellen Rettungsprozesses für beschädigte Bänder sein kann. Im beschriebenen Fall konnten dadurch alte Studioaufnahmen gerettet und für eine Musikdokumentation digitalisiert werden. Solche Geschichten machen deutlich, wie wertvoll historische Tonaufnahmen sind und wie viel Fachwissen nötig ist, um sie langfristig zu erhalten.', '2026-08-27', 'exact', 'approved', 'wix', NULL);
